mapper.select:
select a.REGIST_SEQNO from (
SELECT
@rownum:=@rownum+1 rownum,
a.REGIST_SEQNO,
IF( @prod_id = a.prod_id, @rank := @rank + 1, @rank := 1 ) AS myrank,
@prod_id := a.prod_id
FROM
( SELECT * FROM CHB_PRD_ISSUE_SUB_HIS  ORDER BY ifnull( UPDATE_TIME, CREATE_TIME ) ) a,
( SELECT @rownum := 0, @prod_id := NULL, @rank := 0 )b
where

    a.prod_id = #{item.prodId,jdbcType=VARCHAR}

)a
where 1=1 limit 1
